{
  "project_id": "14409caed5a645d2a107",
  "name": "todo-create",
  "entrypoint_path": "index.ts",
  "import_map_path": "",
  "verify_jwt": true,
  "files": [
    {
      "name": "index.ts",
      "content": "import { createClient } from "npm:@supabase/supabase-js@2";

const json = (data: unknown, status: number) =>
  new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json" },
  });

Deno.serve(async (req: Request) => {
  if (req.method !== "POST") {
    return json({ error: "Method not allowed" }, 405);
  }

  const authorization = req.headers.get("Authorization");
  if (!authorization) {
    return json({ error: "Authorization header is required" }, 401);
  }

  let payload: unknown;
  try {
    payload = await req.json();
  } catch {
    return json({ error: "Invalid JSON body" }, 400);
  }

  if (
    typeof payload !== "object" ||
    payload === null ||
    !("body" in payload) ||
    typeof payload.body !== "string"
  ) {
    return json({ error: "A string body is required" }, 400);
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? "",
    { global: { headers: { Authorization: authorization } } },
  );

  const { data, error } = await supabase
    .from("todos")
    .insert({ body: payload.body })
    .select()
    .single();

  if (error) {
    return json({ error: error.message }, 500);
  }

  return json(data, 201);
});
"
    }
  ]
}

